fun <T> List<T>.secondOrNull110(): T? = if (size > 1) this[1] else null

fun render110(values: List<String>?): String {
    return values?.filter { it.isNotBlank() }?.joinToString(separator = ",") ?: "empty"
}
sealed class Outcome111 {
    data class Success(val payload: String) : Outcome111()
    data object Failure : Outcome111()
}

fun describe111(outcome: Outcome111): String = when (outcome) {
    is Outcome111.Success -> outcome.payload
    Outcome111.Failure -> "failed"
}
class Counter112 {
    var current: Int by Delegates.observable(65) { _, _, new -> println(new) }

    suspend fun advance(): Int {
        try {
            current += 1
        } catch (failure: IllegalStateException) {
            current = 0
        } finally {
            println("advanced")
        }
        return current
    }
}
